// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 deposit) internal {
        deposit = bound(deposit, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= deposit);
        uint256 beforeRecorded;
        try c.getBalance(address(this)) returns (uint256 __r) { beforeRecorded = __r; } catch { return; }
        uint beforeContractBalance = address(c).balance;
        bool reverted;
        try c.addToBalance{value: deposit}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterRecorded;
        try c.getBalance(address(this)) returns (uint256 __r) { afterRecorded = __r; } catch { return; }
        uint afterContractBalance = address(c).balance;
        assertTrue((reverted && afterRecorded == beforeRecorded && afterContractBalance == beforeContractBalance)
            || (!reverted && afterRecorded == beforeRecorded + deposit && afterContractBalance == beforeContractBalance + deposit));
    }

    function testFuzz_run(uint256 deposit) public {
        _run(deposit);
    }

    receive() external payable {}
}
